// Checks the committed validation records (validation/*.json, written by the scripts beside
// them) against the app's accuracy claims, and that About and the example description quote
// those records' numbers. It runs no stitching: the records are regenerated by the validation
// scripts, and the browser test (e2e/smoke.spec.js) holds the app's code to the output hashes
// in example-reference.json.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

const read = (name) => JSON.parse(readFileSync(new URL(`../validation/${name}`, import.meta.url), "utf8"));

test("on the example every tile is within 1 px of Fiji's Grid/Collection stitching", () => {
  const reference = read("example-reference.json");
  assert.equal(reference.positions.tiles.length, 16);
  assert.equal(reference.pairs.count, 42);
  assert.ok(reference.positions.largestDifference < 0.5, `${reference.positions.largestDifference} px`);
  assert.ok(reference.pairs.largestDifference < 1, `${reference.pairs.largestDifference} px`);
  for (const tile of reference.positions.tiles) {
    assert.ok(Math.hypot(tile.app[0] - tile.fiji[0], tile.app[1] - tile.fiji[1]) <= reference.positions.largestDifference + 1e-9);
  }
});

test("a mosaic cut from a real tile is recovered within 0.5 px of its known positions", () => {
  const reference = read("synthetic-real.json");
  assert.equal(reference.tiles, 9);
  assert.ok(reference.largestLayoutError > 10, "the layout starts well away from the truth");
  assert.ok(reference.largestError < 0.5, `${reference.largestError} px`);
  assert.ok(reference.errors.every((tile) => tile.error <= reference.largestError));
});

test("About and the example description quote the committed validation numbers", () => {
  const example = read("example-reference.json");
  const synthetic = read("synthetic-real.json");
  const about = readFileSync(new URL("../index.html", import.meta.url), "utf8");
  const [entry] = JSON.parse(readFileSync(new URL("../examples.json", import.meta.url), "utf8"));
  const twoPlaces = (value) => value.toFixed(2);
  const tiles = twoPlaces(example.positions.largestDifference);
  assert.match(about, new RegExp(`registered positions are within ${tiles} px of Fiji`));
  assert.match(about, new RegExp(`every pair offset within ${twoPlaces(example.pairs.largestDifference)} px`));
  assert.match(about, new RegExp(`every tile was found within ${twoPlaces(synthetic.largestError)} px`));
  assert.match(about, /weighted by r × overlapping pixels/);
  assert.match(entry.expectedResult, new RegExp(`within ${tiles} px of Fiji`));
});
